  List.foldl f' (g a) (List.map g l) = g (List.foldl f a l)

theorem List.map_eq_cons_iff'.{u_1, u_2} {α : Type u_1} {β : Type u_2} {b : β} {l₂ : List β} {f : α → β}
  {l : List α} :
  List.map f l = b :: l₂ ↔ Option.map f l.head? = some b ∧ Option.map (List.map f) l.tail? = some l₂

theorem List.append_eq_map_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {L₁ L₂ : List β} {l : List α}
  {f : α → β} :
  L₁ ++ L₂ = List.map f l ↔ ∃ l₁ l₂, l = l₁ ++ l₂ ∧ List.map f l₁ = L₁ ∧ List.map f l₂ = L₂

theorem List.getLast_filterMap_of_eq_some.{u_1, u_2} {α : Type u_1} {β : Type u_2} {f : α → Option β}
  {l : List α} (w : l ≠ []) {b : β} (h : f (l.getLast w) = some b) :
  (List.filterMap f l).getLast ⋯ = b

