  List.foldr f' (g a) (List.map g l) = g (List.foldr f a l)

theorem List.foldr_map.{u_1, u_2, u_3} {α₁ : Type u_1} {α₂ : Type u_2} {β : Type u_3} {f : α₁ → α₂}
  {g : α₂ → β → β} {l : List α₁} {init : β} :
  List.foldr g init (List.map f l) = List.foldr (fun x y => g (f x) y) init l

theorem List.foldl_map.{u_1, u_2, u_3} {β₁ : Type u_1} {β₂ : Type u_2} {α : Type u_3} {f : β₁ → β₂}
  {g : α → β₂ → α} {l : List β₁} {init : α} :
  List.foldl g init (List.map f l) = List.foldl (fun x y => g x (f y)) init l

theorem List.contains_filterMap.{u_1, u_2} {β : Type u_1} {α : Type u_2} [BEq β] {l : List α} {x : β}
  {f : α → Option β} :
  (List.filterMap f l).contains x = l.any fun a => Option.any (fun b => x == b) (f a)

theorem List.map_flatMap.{u_1, u_2, u_3} {β : Type u_1} {γ : Type u_2} {α : Type u_3} {f : β → γ}
  {g : α → List β} {l : List α} :
  List.map f (List.flatMap g l) = List.flatMap (fun a => List.map f (g a)) l

theorem List.foldlM_reverse.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  [Monad m] {l : List α} {f : β → α → m β} {b : β} :
  List.foldlM f b l.reverse = List.foldrM (fun x y => f y x) b l

theorem List.filter_removeAll_filter.{u_1} {α : Type u_1} [BEq α] [LawfulBEq α] {p : α → Bool}
  {xs ys : List α} :
  (List.filter p xs).removeAll (List.filter p ys) = (List.filter p xs).removeAll ys

theorem List.foldlRecOn_nil.{u_1, u_2, u_3} {β : Type u_1} {α : Type u_2} {b : β} {motive : β → Sort u_3}
  {op : β → α → β} (hb : motive b) (hl : (b : β) → motive b → (a : α) → a ∈ [] → motive (op b a)) :
  List.foldlRecOn [] op hb hl = hb

theorem List.flatMap_assoc.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {l : List α}
  {f : α → List β} {g : β → List γ} :
  List.flatMap g (List.flatMap f l) = List.flatMap (fun x => List.flatMap g (f x)) l

