theorem List.map_filterMap_some_eq_filter_map_isSome.{u_1, u_2} {α : Type u_1} {β : Type u_2}
  {f : α → Option β} {l : List α} :
  List.map some (List.filterMap f l) = List.filter (fun b => b.isSome) (List.map f l)

