theorem List.foldr_eq_apply_foldl.{u_1} {α : Type u_1} {init x : α} {xs : List α} {f : α → α → α}
  [Std.Associative f] [Std.LawfulLeftIdentity f init] :
  List.foldr f x xs = f (List.foldl f init xs) x

