theorem List.foldl_flatMap.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {f : α → List β}
  {g : γ → β → γ} {l : List α} {init : γ} :
  List.foldl g init (List.flatMap f l) = List.foldl (fun acc x => List.foldl g acc (f x)) init l
